using System.Text.Json.Serialization;

namespace Bazaar.Contracts.Telemetry;

/// <summary>Schema identifiers for crash reports (doc 43, section 5.1).</summary>
public static class CrashReportSchemas
{
    /// <summary>The first crash report schema. Field names are fixed for this version.</summary>
    public const string V1 = "bazaar.crash/1";
}

/// <summary>
/// One crash report as the client builds it on the device (doc 43, sections 4.1 and 5.1). Every field is set from the
/// schema; nothing is generated by a model. Wire names are snake_case through <see cref="CrashContractsJsonContext"/>.
/// <see cref="Fingerprint"/> is the device's hint; the server recomputes it (section 8).
/// </summary>
public sealed record CrashReport(
    string Schema,
    Guid ReportId,
    DateTimeOffset CreatedAt,
    Guid InstallId,
    CrashClientInfo Client,
    CrashErrorInfo Error,
    IReadOnlyList<CrashFrame> Stack,
    int? FlaggedFrame,
    IReadOnlyList<CrashModuleInfo> Modules,
    IReadOnlyList<CrashLogEntry> Logs,
    CrashDeviceInfo Device,
    CrashScreenInfo Screen,
    CrashRedactionInfo Redaction,
    string? Fingerprint,
    CrashConsentInfo Consent);

/// <summary>The app that crashed. <see cref="Channel"/> is the operator's release channel (doc 43, section 5.1).</summary>
public sealed record CrashClientInfo(string Kind, string Version, string Channel, string Runtime);

/// <summary>
/// The error. <see cref="Code"/> is null for an unhandled exception with no registered code (section 4.1).
/// <see cref="Message"/> is already redacted. <see cref="MessageFingerprintInput"/> feeds the fingerprint rule of section 8.
/// </summary>
public sealed record CrashErrorInfo(string? Code, string Type, string Message, string? MessageFingerprintInput);

/// <summary>
/// One stack frame (section 4.1). <see cref="IlOffset"/> and <see cref="MethodToken"/> let the server map the frame to a
/// line from the symbol bundle. <see cref="Line"/> and <see cref="File"/> are null when the build has no line information.
/// <see cref="App"/> is true for a Bazaar module.
/// </summary>
public sealed record CrashFrame(
    string Module,
    string ModuleBuildId,
    string Type,
    string Method,
    int MethodToken,
    int IlOffset,
    int? Line,
    string? File,
    bool App);

/// <summary>A loaded module with its version and deterministic build id (section 4.1).</summary>
public sealed record CrashModuleInfo(string Id, string Version, string BuildId);

/// <summary>
/// One recent log entry (section 4.1). <see cref="Msg"/> is the message template; interpolated values are already
/// redacted. <see cref="Props"/> holds only the allow-listed keys, by type (section 5.3).
/// </summary>
public sealed record CrashLogEntry(
    [property: JsonPropertyName("t")] DateTimeOffset Time,
    string Level,
    string Cat,
    string Msg,
    [property: JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)] CrashLogProperties? Props);

/// <summary>
/// Device information (section 4.1). The client never sends hostname, user name, serial numbers, MAC or IP addresses.
/// <see cref="RamBucket"/> is a bucket such as <c>16-32 GiB</c>, not an exact amount.
/// </summary>
public sealed record CrashDeviceInfo(
    string OsFamily,
    string OsVersion,
    string Arch,
    string RamBucket,
    double DisplayScale,
    string DeviceClass,
    string Posture,
    string Locale);

/// <summary>Screen capture state (section 4.1). <see cref="AttachmentId"/> is null when no screenshot was sent.</summary>
public sealed record CrashScreenInfo(Guid? AttachmentId, CrashMaskingInfo Masking);

/// <summary>What the masking step did to the screenshot. <see cref="PanesUnknown"/> counts panes with no declared regions.</summary>
public sealed record CrashMaskingInfo(int Regions, int PanesUnknown);

/// <summary>Redaction summary (section 5.1). <see cref="ResidualScan"/> is the result of the final scan, such as <c>pass</c>.</summary>
public sealed record CrashRedactionInfo(string RulesVersion, CrashRedactionCounts Counts, string ResidualScan);

/// <summary>Counts of redaction hits by rule kind, and of truncations (section 5.2).</summary>
public sealed record CrashRedactionCounts(int Pattern, int Structural, int Exact, int Truncated);

/// <summary>The consent state that allowed this report (section 7). Values are the section 7 spellings.</summary>
public sealed record CrashConsentInfo(string Mode, string Decision, string Screenshot);
